export const STRINGS=[{name:'G',midi:[55,57,59,60,62]},{name:'D',midi:[62,64,65,67,69]},{name:'A',midi:[69,71,72,74,76]},{name:'E',midi:[76,77,79,81,83]}];
export const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y,a.z!==undefined?(a.z-(b.z||0)):0);
export function angle(a,b,c){const u=[a.x-b.x,a.y-b.y,(a.z||0)-(b.z||0)],v=[c.x-b.x,c.y-b.y,(c.z||0)-(b.z||0)];return Math.acos(Math.max(-1,Math.min(1,u.reduce((s,n,i)=>s+n*v[i],0)/(Math.hypot(...u)*Math.hypot(...v)||1))))*180/Math.PI;}
export function handPose(p){const extended=[8,12,16,20].map(t=>angle(p[t-3],p[t-2],p[t])>155&&distance(p[t],p[0])>distance(p[t-2],p[0])*1.13);const scale=distance(p[0],p[9]);const thumbOnly=!extended.some(Boolean)&&distance(p[4],p[5])>scale*.65&&Math.abs(p[4].y-p[2].y)>scale*.38&&Math.abs(p[4].y-p[2].y)>Math.abs(p[4].x-p[2].x)*1.25;return {count:extended.filter(Boolean).length,thumb:thumbOnly?(p[4].y<p[2].y?1:-1):0,point:extended[0]&&!extended.slice(1).some(Boolean),hook:!extended[0]&&!extended.slice(1).some(Boolean)&&angle(p[5],p[6],p[8])<150&&distance(p[6],p[0])>scale*.9&&distance(p[8],p[5])>scale*.22};}
export function mouthO(p,wasOn=false){if(!p?.length)return false;const width=distance(p[61],p[291]),height=distance(p[13],p[14]),face=distance(p[234],p[454]);return height/width>(wasOn?.27:.38)&&width/face<(wasOn?.38:.34);}
export function noteInfo(s,f,h=false){const midi=STRINGS[s].midi[f]+(h?12:0);return {midi,name:['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][midi%12],octave:Math.floor(midi/12)-1,hz:440*2**((midi-69)/12)};}
